  6→/// ERC-20 Transfer event signature: keccak256("Transfer(address,address,uint256)")
  7→const ERC20_TRANSFER_TOPIC: &str =
  8→    "0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef";
  9→
 10→/// Parse an EVM transaction (stored as Bronze layer) into Silver-layer LedgerEntries.
 11→///
 12→/// Handles:
 13→/// - ERC-20 Transfer events (decoded from log topics/data)
 14→/// - Native ETH value transfers (from raw_metadata.value if present)
 15→/// - Gas fees (from raw_metadata)
 16→pub fn parse_evm_transaction(tx: &Transaction) -> anyhow::Result<Vec<LedgerEntry>> {
 17→    let mut entries = Vec::new();
 18→    let mut entry_index: u32 = 0;
 19→    let wallet = tx.wallet_address.to_lowercase();
 20→
 21→    // 1. Try to parse as an ERC-20 Transfer log
 22→    if let Some(topics) = tx.raw_metadata.get("topics").and_then(|t| t.as_array()) {
 23→        if let Some(topic0) = topics.first().and_then(|t| t.as_str()) {
 24→            if topic0 == ERC20_TRANSFER_TOPIC && topics.len() >= 3 {
 25→                let from = topic_to_address(topics[1].as_str().unwrap_or_default());
 26→                let to = topic_to_address(topics[2].as_str().unwrap_or_default());
 27→
 28→                // Decode uint256 amount from data field
 29→                let data_hex = tx
 30→                    .raw_metadata
 31→                    .get("data")
 32→                    .and_then(|d| d.as_str())
 33→                    .unwrap_or("0x0");
 34→                let amount_bd = hex_to_bigdecimal(data_hex);
 35→
 36→                // The contract address is the token address
 37→                let token_address = tx
 38→                    .raw_metadata
 39→                    .get("address")
 40→                    .and_then(|a| a.as_str())
 41→                    .unwrap_or("unknown")
 42→                    .to_string();
 43→
 44→                let decimals = token_decimals(&token_address);
 45→                let symbol = token_symbol(&token_address);
 46→                let normalized = normalize_bigdecimal(amount_bd, decimals);
 47→
 48→                // Determine if this wallet sent or received
 49→                if from == wallet {
 50→                    // Outgoing transfer
 51→                    entries.push(LedgerEntry {
 52→                        id: deterministic_id(tx.id, entry_index),
 53→                        transaction_id: tx.id,
 54→                        user_id: tx.user_id,
 55→                        wallet_address: tx.wallet_address.clone(),
 56→                        asset_symbol: symbol.clone(),
 57→                        amount: negate(normalized.clone()),
 58→                        entry_type: EntryType::Transfer,
 59→                        fiat_value: None,
 60→                    });
 61→                    entry_index += 1;
 62→                }
 63→
 64→                if to == wallet {
 65→                    // Incoming transfer
 66→                    entries.push(LedgerEntry {
 67→                        id: deterministic_id(tx.id, entry_index),
 68→                        transaction_id: tx.id,
 69→                        user_id: tx.user_id,
 70→                        wallet_address: tx.wallet_address.clone(),
 71→                        asset_symbol: symbol,
 72→                        amount: normalized,
 73→                        entry_type: EntryType::Transfer,
 74→                        fiat_value: None,
 75→                    });
 76→                    entry_index += 1;
 77→                }
 78→            }
 79→        }
 80→    }
 81→
 82→    // 2. Native ETH value (if present in metadata, e.g. from transaction receipt)
 83→    if let Some(value_hex) = tx.raw_metadata.get("value").and_then(|v| v.as_str()) {
 84→        let wei = hex_to_u128(value_hex);
 85→        if wei > 0 {
 86→            let eth_amount = wei_to_eth(wei);
 87→
 88→            // Determine direction from "from"/"to" fields if present
 89→            let from = tx
 90→                .raw_metadata
 91→                .get("from")
 92→                .and_then(|f| f.as_str())
 93→                .unwrap_or_default()
 94→                .to_lowercase();
 95→            let to = tx
 96→                .raw_metadata
 97→                .get("to")
 98→                .and_then(|t| t.as_str())
 99→                .unwrap_or_default()
100→                .to_lowercase();
101→
102→            if from == wallet {
103→                entries.push(LedgerEntry {
104→                    id: deterministic_id(tx.id, entry_index),
105→                    transaction_id: tx.id,
106→                    user_id: tx.user_id,
107→                    wallet_address: tx.wallet_address.clone(),
108→                    asset_symbol: "ETH".to_string(),
109→                    amount: negate(eth_amount.clone()),
110→                    entry_type: EntryType::Transfer,
111→                    fiat_value: None,
112→                });
113→                entry_index += 1;
114→            }
115→
116→            if to == wallet {
117→                entries.push(LedgerEntry {
118→                    id: deterministic_id(tx.id, entry_index),
119→                    transaction_id: tx.id,
120→                    user_id: tx.user_id,
121→                    wallet_address: tx.wallet_address.clone(),
122→                    asset_symbol: "ETH".to_string(),
123→                    amount: eth_amount,
124→                    entry_type: EntryType::Transfer,
125→                    fiat_value: None,
126→                });
127→                entry_index += 1;
128→            }
129→        }
130→    }
131→
132→    // 3. Gas fee (if gas_used and effective_gas_price present)
133→    if let (Some(gas_used_hex), Some(gas_price_hex)) = (
134→        tx.raw_metadata.get("gas_used").and_then(|g| g.as_str()),
135→        tx.raw_metadata
136→            .get("effective_gas_price")
137→            .and_then(|g| g.as_str()),
138→    ) {
139→        let gas_used = hex_to_u128(gas_used_hex);
140→        let gas_price = hex_to_u128(gas_price_hex);
141→        let fee_wei = gas_used.saturating_mul(gas_price);
142→
143→        if fee_wei > 0 {
144→            let fee_eth = wei_to_eth(fee_wei);
145→            entries.push(LedgerEntry {
146→                id: deterministic_id(tx.id, entry_index),
147→                transaction_id: tx.id,
148→                user_id: tx.user_id,
149→                wallet_address: tx.wallet_address.clone(),
150→                asset_symbol: "ETH".to_string(),
151→                amount: negate(fee_eth),
152→                entry_type: EntryType::Fee,
153→                fiat_value: None,
154→            });
155→            entry_index += 1;
156→        }
157→    }
158→
159→    let _ = entry_index;
160→    Ok(entries)
161→}
162→
163→/// Extract an address from a 32-byte padded topic (last 20 bytes).
164→fn topic_to_address(topic: &str) -> String {
165→    let stripped = topic.strip_prefix("0x").unwrap_or(topic);
166→    if stripped.len() >= 40 {
167→        // Take last 40 hex chars (20 bytes = Ethereum address)
168→        let addr = &stripped[stripped.len() - 40..];
169→        format!("0x{addr}")
170→    } else {
171→        stripped.to_string()
172→    }
173→}
174→
175→/// Parse a hex string (with optional 0x prefix) into BigDecimal.
176→/// Handles full uint256 range without truncation.
177→fn hex_to_bigdecimal(hex: &str) -> BigDecimal {
178→    let stripped = hex.strip_prefix("0x").unwrap_or(hex);
179→    if stripped.is_empty() {
180→        return BigDecimal::from(0);
181→    }
182→    // Parse hex digits in chunks to build a BigDecimal without overflow
183→    let mut result = BigDecimal::from(0);
184→    let base = BigDecimal::from(16);
185→    for ch in stripped.chars() {
186→        let digit = match ch.to_ascii_lowercase() {
187→            '0'..='9' => ch as u32 - '0' as u32,
188→            'a'..='f' => ch as u32 - 'a' as u32 + 10,
189→            _ => return BigDecimal::from(0),
190→        };
191→        result = result * &base + BigDecimal::from(digit);
192→    }
193→    result
194→}
195→
196→/// Parse a hex string (with optional 0x prefix) into u128.
197→/// Suitable for values known to fit in u128 (e.g., gas values).
198→fn hex_to_u128(hex: &str) -> u128 {
199→    let stripped = hex.strip_prefix("0x").unwrap_or(hex);
200→    if stripped.is_empty() {
201→        return 0;
202→    }
203→    u128::from_str_radix(stripped, 16).unwrap_or(0)
204→}
205→
206→/// Convert wei (u128) to ETH as BigDecimal (divide by 10^18).
207→fn wei_to_eth(wei: u128) -> BigDecimal {
208→    use bigdecimal::FromPrimitive;
209→    let wei_bd = BigDecimal::from_u128(wei).unwrap_or_default();
210→    let divisor = BigDecimal::from_u128(1_000_000_000_000_000_000u128).unwrap_or_default();
211→    wei_bd / divisor
212→}
213→
214→/// Lookup the number of decimals for well-known ERC-20 tokens.
215→/// Defaults to 18 for unknown tokens.
216→fn token_decimals(contract_address: &str) -> u32 {
217→    match contract_address.to_lowercase().as_str() {
218→        "0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48" => 6, // USDC
219→        "0xdac17f958d2ee523a2206206994597c13d831ec7" => 6, // USDT
220→        "0x2260fac5e5542a773aa44fbcfedf7c193bc2c599" => 8, // WBTC
221→        "0x6b175474e89094c44da98b954eedeac495271d0f" => 18, // DAI
222→        "0xc02aaa39b223fe8d0a0e5c4f27ead9083c756cc2" => 18, // WETH
223→        "0x514910771af9ca656af840dff83e8264ecf986ca" => 18, // LINK
224→        "0x1f9840a85d5af5bf1d1762f925bdaddc4201f984" => 18, // UNI
225→        "0x95ad61b0a150d79219dcf64e1e6cc01f0b64c4ce" => 18, // SHIB
226→        _ => 18,
227→    }
228→}
229→
230→/// Lookup a human-readable symbol for well-known ERC-20 tokens.
231→/// Falls back to the contract address for unknown tokens.
232→fn token_symbol(contract_address: &str) -> String {
233→    match contract_address.to_lowercase().as_str() {
234→        "0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48" => "USDC".to_string(),
235→        "0xdac17f958d2ee523a2206206994597c13d831ec7" => "USDT".to_string(),
236→        "0x2260fac5e5542a773aa44fbcfedf7c193bc2c599" => "WBTC".to_string(),
237→        "0x6b175474e89094c44da98b954eedeac495271d0f" => "DAI".to_string(),
238→        "0xc02aaa39b223fe8d0a0e5c4f27ead9083c756cc2" => "WETH".to_string(),
239→        "0x514910771af9ca656af840dff83e8264ecf986ca" => "LINK".to_string(),
240→        "0x1f9840a85d5af5bf1d1762f925bdaddc4201f984" => "UNI".to_string(),
241→        "0x95ad61b0a150d79219dcf64e1e6cc01f0b64c4ce" => "SHIB".to_string(),
242→        _ => contract_address.to_string(),
243→    }
244→}
245→
246→/// Normalize a raw token amount by dividing by 10^decimals.
247→/// Normalize a BigDecimal raw amount by dividing by 10^decimals.
248→fn normalize_bigdecimal(raw: BigDecimal, decimals: u32) -> BigDecimal {
249→    use std::str::FromStr;
250→    let divisor = BigDecimal::from_str(&format!("1{}", "0".repeat(decimals as usize)))
251→        .unwrap_or_else(|_| BigDecimal::from(1));
252→    raw / divisor
253→}
254→
255→/// Negate a BigDecimal value.
256→fn negate(val: BigDecimal) -> BigDecimal {
257→    -val
258→}
