   1→//! V2 Connector trait and typed filter specifications.
   2→//!
   3→//! This module introduces a filter-driven connector abstraction that accepts
   4→//! typed `IndexTarget` specs instead of bare wallet addresses. It defines:
   5→//!
   6→//! - The `Connector` async trait with `backfill` and `stream` methods
   7→//! - `ConnectorCapabilities` describing what a connector supports
   8→//! - Typed filter spec structs parsed from `IndexTarget.filter_spec` JSONB
   9→//! - Validation helpers for target-connector compatibility
  10→
  11→use serde::{Deserialize, Serialize};
  12→use tokio::sync::mpsc;
  13→
  14→use crate::v2::{ChainFamily, IndexTarget, IngestionBatch, RawTransaction, TargetKind, TargetMode};
  15→
  16→// ---------------------------------------------------------------------------
  17→// Connector capabilities
  18→// ---------------------------------------------------------------------------
  19→
  20→/// Describes the capabilities of a specific connector implementation.
  21→#[derive(Debug, Clone)]
  22→pub struct ConnectorCapabilities {
  23→    /// Which target kinds this connector can handle.
  24→    pub supported_target_kinds: Vec<TargetKind>,
  25→    /// Which ingestion modes this connector supports.
  26→    pub supported_modes: Vec<TargetMode>,
  27→    /// The chain family this connector serves.
  28→    pub chain_family: ChainFamily,
  29→}
  30→
  31→impl ConnectorCapabilities {
  32→    /// Returns `true` if the connector supports the given target kind.
  33→    pub fn supports_target_kind(&self, kind: TargetKind) -> bool {
  34→        self.supported_target_kinds.contains(&kind)
  35→    }
  36→
  37→    /// Returns `true` if the connector supports the given mode.
  38→    pub fn supports_mode(&self, mode: TargetMode) -> bool {
  39→        match mode {
  40→            TargetMode::Both => {
  41→                self.supported_modes.contains(&TargetMode::Backfill)
  42→                    || self.supported_modes.contains(&TargetMode::Both)
  43→            }
  44→            _ => self.supported_modes.contains(&mode),
  45→        }
  46→    }
  47→
  48→    /// Returns `true` if the connector can service the given target.
  49→    pub fn can_service(&self, target: &IndexTarget) -> bool {
  50→        self.chain_family == target.chain_family && self.supports_target_kind(target.kind)
  51→    }
  52→}
  53→
  54→// ---------------------------------------------------------------------------
  55→// Connector trait
  56→// ---------------------------------------------------------------------------
  57→
  58→/// A filter-driven connector that accepts typed target specs for ingestion.
  59→///
  60→/// This replaces the wallet-only `ChainIngestor` trait. Each connector
  61→/// implementation serves one `ChainFamily` and declares which `TargetKind`s
  62→/// and `TargetMode`s it supports via `capabilities()`.
  63→///
  64→/// The control plane (orchestrator) is responsible for:
  65→/// - routing targets to the correct connector based on capabilities
  66→/// - coordinating backfill+stream when `mode = Both` across connectors
  67→/// - managing checkpoints and ingestion runs
  68→#[async_trait::async_trait]
  69→pub trait Connector: Send + Sync {
  70→    /// Declare what this connector can do.
  71→    fn capabilities(&self) -> ConnectorCapabilities;
  72→
  73→    /// Fetch historical data for a target.
  74→    ///
  75→    /// - `target`: the registered index target with its filter spec
  76→    /// - `cursor`: optional checkpoint cursor (opaque JSON from a previous run)
  77→    /// - `limit`: maximum number of raw transactions to return
  78→    ///
  79→    /// Returns an `IngestionBatch` containing raw transactions and an optional
  80→    /// updated cursor for the next call.
  81→    async fn backfill(
  82→        &self,
  83→        target: &IndexTarget,
  84→        cursor: Option<&serde_json::Value>,
  85→        limit: usize,
  86→    ) -> anyhow::Result<IngestionBatch>;
  87→
  88→    /// Open a real-time stream for a target.
  89→    ///
  90→    /// - `target`: the registered index target with its filter spec
  91→    /// - `cursor`: optional checkpoint cursor to resume from
  92→    ///
  93→    /// Returns a channel receiver that yields raw transactions as they arrive.
  94→    /// The background task is spawned internally; dropping the receiver stops it.
  95→    ///
  96→    /// Default implementation returns an error for connectors that only
  97→    /// support backfill.
  98→    async fn stream(
  99→        &self,
 100→        _target: &IndexTarget,
 101→        _cursor: Option<&serde_json::Value>,
 102→    ) -> anyhow::Result<mpsc::Receiver<RawTransaction>> {
 103→        anyhow::bail!(
 104→            "streaming not supported by this connector ({})",
 105→            self.capabilities().chain_family
 106→        )
 107→    }
 108→}
 109→
 110→// ---------------------------------------------------------------------------
 111→// Typed filter specs
 112→// ---------------------------------------------------------------------------
 113→
 114→/// Wallet-specific filter (optional narrowing beyond the address).
 115→/// Per TARGET_MODEL.md Section 2.1.
 116→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 117→pub struct WalletFilterSpec {
 118→    /// Restrict downstream matches to specific assets.
 119→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 120→    pub asset_filter: Vec<String>,
 121→    /// Minimum amount threshold for matches.
 122→    #[serde(default, skip_serializing_if = "Option::is_none")]
 123→    pub min_amount: Option<String>,
 124→    /// Restrict to specific transfer directions.
 125→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 126→    pub directions: Vec<String>,
 127→}
 128→
 129→/// Contract-specific filter (EVM only).
 130→/// Per TARGET_MODEL.md Section 2.2.
 131→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 132→pub struct ContractFilterSpec {
 133→    /// ABI event signatures to filter (e.g. "Transfer(address,address,uint256)").
 134→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 135→    pub event_signatures: Vec<String>,
 136→    /// Additional topic-position filters.
 137→    #[serde(default, skip_serializing_if = "Option::is_none")]
 138→    pub topic_filters: Option<serde_json::Map<String, serde_json::Value>>,
 139→}
 140→
 141→/// Program-specific filter (Solana only).
 142→/// Per TARGET_MODEL.md Section 2.3.
 143→#[derive(Debug, Clone, Serialize, Deserialize)]
 144→pub struct ProgramFilterSpec {
 145→    /// Instruction discriminator bytes to match.
 146→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 147→    pub instruction_discriminators: Vec<String>,
 148→    /// Whether CPI invocations count as matches (default: true).
 149→    #[serde(default = "default_true")]
 150→    pub include_cpi: bool,
 151→}
 152→
 153→impl Default for ProgramFilterSpec {
 154→    fn default() -> Self {
 155→        Self {
 156→            instruction_discriminators: Vec::new(),
 157→            include_cpi: true,
 158→        }
 159→    }
 160→}
 161→
 162→fn default_true() -> bool {
 163→    true
 164→}
 165→
 166→/// Account-specific filter (primarily Solana).
 167→/// Per TARGET_MODEL.md Section 2.4.
 168→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 169→pub struct AccountFilterSpec {
 170→    /// Restrict to write-only or read-only references.
 171→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 172→    pub access_types: Vec<String>,
 173→    /// Informational: program that owns this account.
 174→    #[serde(default, skip_serializing_if = "Option::is_none")]
 175→    pub associated_program: Option<String>,
 176→}
 177→
 178→/// Topic-based filter (EVM only, address is null on the target).
 179→/// Per TARGET_MODEL.md Section 2.5.
 180→#[derive(Debug, Clone, Serialize, Deserialize)]
 181→pub struct TopicFilterSpec {
 182→    /// Up to 4 topic positions. Each is a hex string, null, or an array of hex strings.
 183→    pub topics: Vec<serde_json::Value>,
 184→    /// Optional contract address narrowing.
 185→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 186→    pub address_filter: Vec<String>,
 187→}
 188→
 189→/// Market-specific filter (Hyperliquid only).
 190→/// Per TARGET_MODEL.md Section 2.6.
 191→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 192→pub struct MarketFilterSpec {
 193→    /// Types of market data to fetch.
 194→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 195→    pub data_types: Vec<String>,
 196→    /// Minimum trade size (query-time filter).
 197→    #[serde(default, skip_serializing_if = "Option::is_none")]
 198→    pub min_size: Option<String>,
 199→}
 200→
 201→/// Pool-specific filter (EVM and Solana).
 202→/// Per TARGET_MODEL.md Section 2.7.
 203→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 204→pub struct PoolFilterSpec {
 205→    /// Informational protocol name.
 206→    #[serde(default, skip_serializing_if = "Option::is_none")]
 207→    pub protocol: Option<String>,
 208→    /// Informational token pair.
 209→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 210→    pub token_pair: Vec<String>,
 211→    /// Event types to match.
 212→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 213→    pub event_types: Vec<String>,
