        // Reconstruct cursor from the new last_block
        let new_cursor = json!({"last_block": 19_000_000u64});
        let from2 = cursor_to_from_block(Some(&new_cursor), 20_000_000, 10, 2000);
        assert_eq!(from2, 19_000_001);
    }
}

