        let mut metadata = json!({
            "log_index": 0,
            "block_number": 18_000_000,
            "topics": [],
            "data": "0x",
        });

        if let Some(obj) = metadata.as_object_mut() {
            if let Some(tx_obj) = enrichment_tx.as_object() {
                obj.extend(tx_obj.iter().map(|(k, v)| (k.clone(), v.clone())));
